before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <vector>
int main() {
    std::vector<int> values{2, 4};
    int total{0};
    for (auto it = values.begin(); it != values.end(); ++it) {
        total += *it;
    }
    std::cout << total << '\n';
}

```

